const origin=document.getElementById('shipping-origin'),fields=document.getElementById('fields');
origin.closest('.field').hidden=true;
const button=document.createElement('button');button.type='button';button.className='shipping-launch';button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-controls','shipping-dialog');
button.innerHTML='<svg viewBox="0 0 64 48" aria-hidden="true"><path fill="currentColor" d="M17 5h28l-2 10h11l8 14-3 11h-5a9 9 0 0 0-18 0H26a9 9 0 0 0-18 0H5l2-10h13a3 3 0 0 0 0-6H3a3 3 0 0 1 0-6h23a3 3 0 0 0 0-6H12l1-3a4 4 0 0 1 4-4Zm27 15-2 10h14l-5-10Z"/><circle cx="17" cy="40" r="6" fill="none" stroke="currentColor" stroke-width="4"/><circle cx="45" cy="40" r="6" fill="none" stroke="currentColor" stroke-width="4"/></svg><span>USA</span>';
document.querySelector('.calculator .section-head').append(button);
const dialog=document.createElement('dialog');dialog.id='shipping-dialog';dialog.setAttribute('aria-labelledby','shipping-title');dialog.innerHTML='<div class="shipping-dialog-head"><div><p class="eyebrow">ORIGEN DEL ENVÍO</p><h2 id="shipping-title">¿Desde dónde viene?</h2></div><button type="button" class="shipping-close" aria-label="Cerrar selección de envío">×</button></div><p>Selecciona el origen para calcular el envío del repuesto.</p><div class="shipping-choices"><button type="button" data-origin="USA"><span class="country-code">USA</span><strong>Estados Unidos</strong><span class="shipping-check" aria-hidden="true">✓</span></button><button type="button" data-origin="COLOMBIA"><span class="country-code">COL</span><strong>Colombia</strong><span class="shipping-check" aria-hidden="true">✓</span></button></div>';
document.body.append(dialog);
function sync(){button.disabled=fields.disabled||origin.disabled;const usa=origin.value==='USA';button.querySelector('span').textContent=usa?'USA':'COL';button.setAttribute('aria-label','Origen del envío: '+(usa?'Estados Unidos':'Colombia')+'. Cambiar');button.title='Cambiar origen del envío';for(const choice of dialog.querySelectorAll('[data-origin]'))choice.setAttribute('aria-pressed',String(choice.dataset.origin===origin.value));}
button.onclick=()=>{sync();dialog.showModal();dialog.querySelector('[aria-pressed=true]').focus();};dialog.querySelector('.shipping-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>button.focus());
for(const choice of dialog.querySelectorAll('[data-origin]'))choice.onclick=()=>{if(button.disabled)return;const changed=origin.value!==choice.dataset.origin;origin.value=choice.dataset.origin;if(changed){origin.dispatchEvent(new Event('input',{bubbles:true}));origin.dispatchEvent(new Event('change',{bubbles:true}));}sync();dialog.close();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)button.animate([{transform:'scale(.94)'},{transform:'scale(1)'}],{duration:220,easing:'ease-out'});};
origin.addEventListener('change',sync);new MutationObserver(sync).observe(fields,{attributes:true,attributeFilter:['disabled']});setInterval(()=>{if(!document.hidden)sync();},300);sync();
